//! Submit native listings and dispatch work generated by terminal input.
use super::{App, Configuration, Controller, Instant, Pool, Request, RequestKind, io, ui};
use crate::{clipboard::runtime::Runtime, operations::Queue};

pub(super) fn initial_listings(app: &App, pool: &mut Pool) {
    for (pane, state) in app
        .panes
        .iter()
        .enumerate()
        .filter(|(_, state)| !state.is_remote())
    {
        pool.submit(Request {
            pane,
            generation: 1,
            path: Some(state.local_path().clone()),
            kind: RequestKind::Listing,
        });
    }
}

pub(super) fn deferred_listings(app: &mut App, pool: &mut Pool) {
    for pane in 0..2 {
        if let Some(request) = app.take_refresh(pane) {
            pool.submit(request);
        }
    }
}

pub(super) fn dispatch_event(
    controller: &mut Controller,
    geometry: &ui::Geometry,
    started: Instant,
    pool: &mut Pool,
    jobs: &mut Queue,
    config: &mut Configuration,
    clipboard: &mut Runtime,
) -> io::Result<()> {
    let requests = controller.handle(crossterm::event::read()?, geometry, started.elapsed());
    for request in requests {
        pool.submit(request);
    }
    config.synchronize(controller);
    super::operations::submit(controller, jobs);
    super::clipboard::submit(controller, clipboard);
    Ok(())
}
